import React from 'react';
import { useStatus } from '../contexts/StatusContext';
import { 
  MenuIcon, 
  AnimatedNotificationIcon, 
  AnimatedRefreshIcon,
  SettingsIcon,
  NetworkIcon,
  LoadingIcon
} from "./Icons";

interface HeaderProps {
  onSidebarToggle: () => void;
  sidebarOpen: boolean;
}

export const Header: React.FC<HeaderProps> = ({ onSidebarToggle, sidebarOpen }) => {
  const { state } = useStatus();

  const getStatusColor = () => {
    if (state.connectionStatus === "connected") {
      return "bg-success-500";
    } else if (state.connectionStatus === "connecting") {
      return "bg-warning-500";
    } else {
      return "bg-error-500";
    }
  };

  const getStatusText = () => {
    switch (state.connectionStatus) {
      case "connected":
        return "Connected";
      case "connecting":
        return "Connecting...";
      case "disconnected":
        return "Disconnected";
      case "error":
        return "Connection Error";
      default:
        return "Unknown";
    }
  };

  return (
    <header className="glass border-b border-secondary-200 px-4 lg:px-6 py-4 animate-slide-in-top">
      <div className="flex items-center justify-between">
        {/* Left side */}
        <div className="flex items-center space-x-4">
          {/* Mobile menu button */}
          <button
            onClick={onSidebarToggle}
            className="lg:hidden p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-full focus-ring transition-all duration-200"
          >
            <MenuIcon size="lg" />
          </button>

          {/* Desktop sidebar toggle */}
          <button
            onClick={onSidebarToggle}
            className="hidden lg:block p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-full focus-ring transition-all duration-200"
          >
            <MenuIcon size="lg" />
          </button>

          {/* Page title */}
          <div className="hidden sm:block animate-slide-in-left">
            <h1 className="text-2xl font-bold text-gradient neon-glow">
              TetraCore StreamHub
            </h1>
            <p className="text-sm text-secondary-600 animate-slide-in-bottom">
              Real-time monitoring dashboard
            </p>
          </div>
        </div>

        {/* Right side */}
        <div className="flex items-center space-x-4">
          {/* Connection status */}
          <div className="hidden md:flex items-center space-x-3 px-4 py-2 glass-colored rounded-full animate-floating">
            {state.connectionStatus === "connecting" ? (
              <LoadingIcon size="sm" className="text-warning-500 animate-glow-warning" />
            ) : (
              <NetworkIcon size="sm" className={`${
                state.connectionStatus === "connected" 
                  ? "text-success-500 animate-glow-success" 
                  : "text-error-500 animate-glow-error"
              } animate-bounce-gentle`} />
            )}
            <span className="text-sm font-medium text-secondary-800 animate-text-shimmer">
              {getStatusText()}
            </span>
          </div>

          {/* Notifications */}
          <button className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-full focus-ring relative transition-all duration-200 group">
            <AnimatedNotificationIcon size="lg" className="group-hover:text-primary-500" />
            {state.alerts.length > 0 && (
              <span className="absolute -top-1 -right-1 h-5 w-5 bg-error-500 text-white text-xs rounded-full flex items-center justify-center animate-bounce shadow-lg">
                {state.alerts.length > 9 ? '9+' : state.alerts.length}
              </span>
            )}
          </button>

          {/* Refresh button */}
          <button
            onClick={() => window.location.reload()}
            className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-full focus-ring transition-all duration-200 group"
          >
            <AnimatedRefreshIcon size="lg" className="group-hover:text-primary-500" />
          </button>

          {/* Settings */}
          <button className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-full focus-ring transition-all duration-200">
            <SettingsIcon size="lg" />
          </button>
        </div>
      </div>
    </header>
  );
};
